// Existing exports are preserved.

/**
 * Refresh the given session timestamp.
 * - If the session is expired with respect to the provided 'now', return null.
 * - Otherwise return a new Session with lastActivityAt updated to 'now'.
 */
export function refreshSession(session: Session, now: Date): Session | null {
  // Session is considered expired if now is after or equal to lastActivityAt + 30 minutes
  // as per ADR-001 decision: boundary at exactly 30 minutes counts as expired.
  const THIRTY_MINUTES_MS = 30 * 60 * 1000;

  const last = session.lastActivityAt.getTime();
  const current = now.getTime();

  if (current - last >= THIRTY_MINUTES_MS) {
    return null;
  }

  // Return a new session object with updated lastActivityAt
  return {
    ...session,
    lastActivityAt: new Date(now.getTime()),
  };
}

