// Helper to check expiration: 30 minutes since lastActivityAt
export function isSessionExpired(session: Session, now: string): boolean {
  const last = new Date(session.lastActivityAt).getTime();
  const current = new Date(now).getTime();
  const elapsedMs = current - last;
  const THRESHOLD_MS = 30 * 60 * 1000; // 30 minutes
  return elapsedMs >= THRESHOLD_MS;
}

